  if(kind==='proposal'){const a=items.find(a=>a.id===v('appointment_id'));if(await stage(salon()+'/proposals','POST',{customer_id:a.customer_id,professional_id:v('professional_id'),service_id:v('service_id'),start:iso(v('start')),expires_minutes:Math.round(Number(v('hours'))*60),replace_id:v('replace')?a.id:null},'Propor atendimento'))$('salon-dialog').close();return;}
  if(kind==='opening-hours'){editConfig(c=>{c.opening_hours||=[];c.opening_hours.push({weekday:Number(v('weekday')),start:v('start'),end:v('end')});});return;}
  if(kind==='module'){editConfig(c=>{c.enabled=f.has('enabled');c.product_sales=f.has('product_sales');c.timezone=v('timezone');});return;}
