  if(kind==='service'){editConfig(c=>{const id=v('id')||crypto.randomUUID(),s={id,name:v('name').trim(),minutes:Number(v('minutes')),price_cents:Math.round(Number(v('price'))*100),enabled:f.has('enabled'),return_days:Math.max(0,Math.min(365,Math.round(Number(v('returnDays'))||0)))},i=c.services.findIndex(x=>x.id===id);if(i<0)c.services.push(s);else c.services[i]=s;});$('salon-dialog').close();return;}
