 function loginPage(){page='account';$('salon-main').innerHTML=`<section class="hero"><span class="eyebrow">Seu espaço profissional</span><h1>Uma agenda que acompanha você.</h1><p>Ative seu acesso com o convite fornecido pelo salão.</p></section><form class="panel stack" data-form="activation"><label class="field">Código de convite<input name="code" autocomplete="off" required></label><button class="btn primary">Ativar meu acesso</button></form><a class="btn full" href="${esc(link('customer'))}">Voltar ao salão</a>`;$('salon-nav').replaceChildren();window.ElumeSalonIcons?.decorate($('salon-main'));}
