   await load();if(role==='professional'){draftKey+=':'+professionalId;try{draft={commands:[],config:null,...JSON.parse(localStorage.getItem(draftKey)||'{}')};}catch{}render();}if(role==='admin'&&!config.data.enabled){page='setup';render();}
